/**
 * Research PC collection (SRS-DAT-015): research packages from the study devices (researchPackage.ts) are opened with
 * the study password, checked again on the PC (each record's seal, each photo's SHA-256) and merged by study code into
 * one export per subject in the app's own JSON format (fpc-export/1), which tools/analysis/pilot.py reads as it is.
 * Photos stay apart from the measures, and only while the subject's latest consent still covers them. Nothing is kept
 * in the browser: the PC user saves what comes out to the encrypted drive.
 */
import type { ResearchConsent } from './consent';
import { canonicalJson, sha256Hex, verify } from './integrity';
import {
  PACKAGE_FORMAT,
  openPackage,
  type PackageContent,
  type PackageFile,
  type PackageHeader,
  type PackagePhoto,
} from './researchPackage';
import type { SessionRecord, SynkRecord } from './types';

export interface LoadedFile {
  name: string;
  file: PackageFile | null;
  /** Why it is not a package. */
  error?: 'NOT_A_PACKAGE' | 'UNREADABLE';
}

/** A dropped or chosen file: a research package (its header is readable without the password), or why not. */
export function readPackageFile(name: string, text: string): LoadedFile {
  let d: unknown;
  try {
    d = JSON.parse(text);
  } catch {
    return { name, file: null, error: 'UNREADABLE' };
  }
  const f = d as PackageFile;
  const ok = f?.format === PACKAGE_FORMAT && f.header?.format === PACKAGE_FORMAT && typeof f.data === 'string' && !!f.kdf && !!f.cipher;
  return ok ? { name, file: f } : { name, file: null, error: 'NOT_A_PACKAGE' };
}

export interface OpenedFile {
  name: string;
  header: PackageHeader;
  content: PackageContent | null;
  error?: 'WRONG_PASSWORD_OR_CHANGED' | 'NOT_A_PACKAGE';
  /** Records (assessments and synkinesis finder) whose seal checks on the PC, of all. */
  seals: { ok: number; total: number };
  /** Photos whose SHA-256 matches, of all. */
  photos: { ok: number; total: number };
}

type Sealed<T> = T & { integrityVerified: boolean };

/** The seal of a record as exported (the device's `integrityVerified` flag is not part of what was sealed). */
async function sealOk<T extends { integrity: { hash: string } }>(x: T & { integrityVerified?: boolean }): Promise<boolean> {
  const { integrityVerified: _, ...record } = x;
  return verify(record as unknown as T);
}

const unb64 = (s: string): Uint8Array => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

/** Opens one package and checks it again; the PC's own seal check replaces the device's `integrityVerified`. */
export async function openFile(f: LoadedFile, password: string): Promise<OpenedFile | null> {
  if (!f.file) return null;
  const header = f.file.header;
  const empty = { seals: { ok: 0, total: 0 }, photos: { ok: 0, total: 0 } };
  let content: PackageContent;
  try {
    ({ content } = await openPackage(f.file, password));
  } catch (e) {
    const error = (e as Error).message === 'NOT_A_PACKAGE' ? 'NOT_A_PACKAGE' : 'WRONG_PASSWORD_OR_CHANGED';
    return { name: f.name, header, content: null, error, ...empty };
  }
  const sessions = await Promise.all(content.sessions.map(async (x) => ({ ...x, integrityVerified: await sealOk(x) })));
  const synk = await Promise.all(content.synkinesisFinder.map(async (x) => ({ ...x, integrityVerified: await sealOk(x) })));
  const photos = await Promise.all(content.photos.map(async (p) => ({ p, ok: (await sha256Hex(unb64(p.jpeg))) === p.sha256 })));
  const checked = [...sessions, ...synk];
  return {
    name: f.name,
    header,
    // Photos that do not match their hash are dropped here.
    content: { ...content, sessions, synkinesisFinder: synk, photos: photos.filter((x) => x.ok).map((x) => x.p) },
    seals: { ok: checked.filter((x) => x.integrityVerified).length, total: checked.length },
    photos: { ok: photos.filter((x) => x.ok).length, total: photos.length },
  };
}

export interface MergedSubject {
  code: string;
  /** Package file names, oldest first. */
  files: string[];
  /** Header of the newest package. */
  latest: PackageHeader;
  subject: PackageContent['subject'];
  consentHistory: ResearchConsent[];
  sessions: Sealed<SessionRecord>[];
  clinicianRatings: PackageContent['clinicianRatings'];
  rehabLogs: PackageContent['rehabLogs'];
  synkinesisFinder: Sealed<SynkRecord>[];
  rejections: PackageContent['rejections'];
  /** Only while the newest package's consent still covers photos. */
  photos: PackagePhoto[];
  /** What the PC user should know (Korean): duplicates that differ, failed seals, photos left out. */
  notes: string[];
}

/** By id; a record that differs between files keeps the copy whose seal checks (else the newest). */
function mergeById<T extends { id: string }>(
  lists: readonly (readonly T[])[],
  good: (x: T) => boolean,
  onConflict: (id: string) => void,
): T[] {
  const out = new Map<string, T>();
  for (const list of lists) {
    for (const x of list) {
      const had = out.get(x.id);
      if (had && canonicalJson(had) !== canonicalJson(x)) {
        onConflict(x.id);
        if (good(had) && !good(x)) continue;
      }
      out.set(x.id, x);
    }
  }
  return [...out.values()];
}

const byTime = <T extends { createdAt?: string; at?: string }>(a: T, b: T) =>
  (a.createdAt ?? a.at ?? '').localeCompare(b.createdAt ?? b.at ?? '');

/** Merges opened packages by study code (files without a code are listed under '(코드 없음)'). */
export function mergeSubjects(opened: readonly OpenedFile[]): MergedSubject[] {
  const groups = new Map<string, OpenedFile[]>();
  for (const f of opened) {
    if (!f.content) continue;
    const code = f.header.subjectCode ?? '(코드 없음)';
    groups.set(code, [...(groups.get(code) ?? []), f]);
  }
  return [...groups.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([code, fs]) => {
      const files = [...fs].sort((a, b) => a.header.exportedAt.localeCompare(b.header.exportedAt));
      const newest = files.at(-1)!;
      const notes: string[] = [];
      const c = files.map((f) => f.content!);
      const conflict = (what: string) => (id: string) =>
        notes.push(`${what} ${id.slice(0, 8)}: 파일마다 내용이 다름 — 봉인이 맞는 쪽을 씀`);
      const sessions = mergeById(
        c.map((x) => x.sessions as Sealed<SessionRecord>[]),
        (x) => x.integrityVerified,
        conflict('평가'),
      ).sort(byTime);
      const synk = mergeById(
        c.map((x) => x.synkinesisFinder as Sealed<SynkRecord>[]),
        (x) => x.integrityVerified,
        conflict('연합운동 찾기'),
      ).sort(byTime);
      const failed = sessions.filter((x) => !x.integrityVerified).length;
      if (failed) notes.push(`평가 ${failed}건의 봉인이 맞지 않음 — 분석 도구가 빼고 계산함`);
      const photosOk = newest.header.consent.items.photos;
      const photoMap = new Map<string, PackagePhoto>();
      for (const x of c) for (const p of x.photos) photoMap.set(`${p.sessionId}:${p.step}`, p);
      if (!photosOk && photoMap.size) notes.push(`최근 동의에 사진이 없어 사진 ${photoMap.size}장을 뺌 — 이전에 받은 원본 파일도 지우세요`);
      const never = () => true;
      const none = () => {};
      return {
        code,
        files: files.map((f) => f.name),
        latest: newest.header,
        subject: newest.content!.subject,
        consentHistory: [...newest.content!.consentHistory],
        sessions,
        clinicianRatings: mergeById(
          c.map((x) => x.clinicianRatings),
          never,
          none,
        ).sort(byTime),
        rehabLogs: mergeById(
          c.map((x) => x.rehabLogs),
          never,
          none,
        ).sort(byTime),
        synkinesisFinder: synk,
        rejections: mergeById(
          c.map((x) => x.rejections),
          never,
          none,
        ).sort(byTime),
        photos: photosOk ? [...photoMap.values()] : [],
        notes,
      };
    });
}

/** One subject in the app's own export format (fpc-export/1, no photos), for tools/analysis. */
export function subjectExport(m: MergedSubject, collectedAt: Date = new Date()) {
  return {
    format: 'fpc-export/1',
    exportedAt: m.latest.exportedAt,
    collectedAt: collectedAt.toISOString(),
    app: m.latest.app,
    subjectCode: m.code,
    subject: m.subject,
    consent: m.latest.consent,
    consentHistory: m.consentHistory,
    sourceFiles: m.files,
    sessions: m.sessions,
    clinicianRatings: m.clinicianRatings,
    rehabLogs: m.rehabLogs,
    synkinesisFinder: m.synkinesisFinder,
    rejections: m.rejections,
  };
}

/** Name of a subject's export file (a code is letters, digits and hyphens). */
export const subjectFileName = (code: string): string => `${code.replace(/[^A-Za-z0-9-]/g, '_')}.json`;
