/**
 * 연구 자료 모으기 (research PC, SRS-DAT-015): open the research packages from the study devices, check them again, merge
 * them by study code and save, for tools/analysis, one fpc-export/1 file per subject, a session CSV, a log and the
 * consented photos apart. Opens without a profile of its own; keeps nothing in the browser.
 */
import { useState } from 'preact/hooks';
import { agreement, csvText, download, sessionCsvRows } from '../../data/export';
import {
  mergeSubjects,
  openFile,
  readPackageFile,
  subjectExport,
  subjectFileName,
  type LoadedFile,
  type OpenedFile,
} from '../../data/collect';
import { APP_INFO } from '../../data/records';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { fmtDate } from '../labels';

type Writable = { write(d: Blob | string): Promise<void>; close(): Promise<void> };
interface DirHandle {
  getDirectoryHandle(name: string, o?: { create?: boolean }): Promise<DirHandle>;
  getFileHandle(name: string, o?: { create?: boolean }): Promise<{ createWritable(): Promise<Writable> }>;
}
const pickDir = (window as unknown as { showDirectoryPicker?: (o?: { mode?: 'readwrite' }) => Promise<DirHandle> }).showDirectoryPicker;

const unb64 = (s: string): Uint8Array => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const f2 = (x: number | null) => (x === null ? '–' : x.toFixed(2));
const day = (iso: string) => iso.slice(0, 10);

export function Collect() {
  const [loaded, setLoaded] = useState<LoadedFile[]>([]);
  const [opened, setOpened] = useState<OpenedFile[]>([]);
  const [pw, setPw] = useState('');
  const [busy, setBusy] = useState<string | null>(null);
  const [msg, setMsg] = useState<{ tone: 'warn' | 'good' | 'danger'; text: string } | null>(null);
  const merged = mergeSubjects(opened);
  const openedBy = new Map(opened.map((o) => [o.name, o]));
  const allSessions = merged.flatMap((m) => m.sessions);
  const ag = agreement(
    allSessions,
    merged.flatMap((m) => m.clinicianRatings),
  );

  const addFiles = async (list: FileList | null) => {
    if (!list) return;
    const got = await Promise.all([...list].map(async (f) => readPackageFile(f.name, await f.text())));
    const names = new Set(loaded.map((f) => f.name));
    setLoaded([...loaded, ...got.filter((f) => !names.has(f.name))]);
    setMsg(null);
  };

  const openAll = async () => {
    setBusy('여는 중… (파일마다 1초쯤)');
    const out: OpenedFile[] = [];
    for (const f of loaded) {
      const o = await openFile(f, pw);
      if (o) out.push(o);
    }
    setOpened(out);
    setBusy(null);
    const bad = out.filter((o) => o.error).length;
    setMsg(
      bad
        ? { tone: 'warn', text: `${bad}개 파일을 열지 못했습니다. 비밀번호가 다르거나 파일이 바뀌었습니다.` }
        : { tone: 'good', text: `${out.length}개 파일을 열었습니다. 봉인과 사진 해시를 다시 확인했습니다.` },
    );
  };

  const outputs = () => {
    const at = new Date();
    const files: { path: string[]; name: string; data: Blob | string }[] = [];
    for (const m of merged) files.push({ path: [], name: subjectFileName(m.code), data: JSON.stringify(subjectExport(m, at), null, 1) });
    files.push({
      path: [],
      name: '_sessions.csv',
      data: csvText(
        merged.flatMap((m) =>
          sessionCsvRows(
            {
              sessions: m.sessions,
              integrity: Object.fromEntries(m.sessions.map((s) => [s.id, s.integrityVerified])),
              ratings: m.clinicianRatings,
            },
            m.code,
          ),
        ),
      ),
    });
    files.push({
      path: [],
      name: '_collect_log.json',
      data: JSON.stringify(
        {
          format: 'fpc-collect-log/1',
          collectedAt: at.toISOString(),
          app: APP_INFO,
          files: loaded.map((f) => {
            const o = openedBy.get(f.name);
            return {
              name: f.name,
              subjectCode: f.file?.header.subjectCode ?? null,
              exportedAt: f.file?.header.exportedAt ?? null,
              opened: !!o?.content,
              error: f.error ?? o?.error ?? null,
              seals: o?.seals ?? null,
              photos: o?.photos ?? null,
            };
          }),
          subjects: merged.map((m) => ({
            code: m.code,
            files: m.files,
            sessions: m.sessions.length,
            photos: m.photos.length,
            notes: m.notes,
          })),
        },
        null,
        1,
      ),
    });
    return files;
  };

  const save = async () => {
    setMsg(null);
    if (!pickDir) {
      // No folder access (not Chrome/Edge): plain downloads, photos as one JSON per subject ('_' first: the analysis
      // tool skips it).
      for (const f of outputs())
        download(f.name, f.data as string, f.name.endsWith('.csv') ? 'text/csv;charset=utf-8' : 'application/json');
      for (const m of merged.filter((x) => x.photos.length))
        download(`_photos_${m.code}.json`, JSON.stringify({ subjectCode: m.code, photos: m.photos }), 'application/json');
      setMsg({ tone: 'good', text: '파일로 내려받았습니다. 암호화 드라이브의 한 폴더로 옮기세요.' });
      return;
    }
    let dir: DirHandle;
    try {
      dir = await pickDir({ mode: 'readwrite' });
    } catch {
      return; // cancelled
    }
    setBusy('저장하는 중…');
    try {
      const write = async (path: string[], name: string, data: Blob | string) => {
        let d = dir;
        for (const p of path) d = await d.getDirectoryHandle(p, { create: true });
        const w = await (await d.getFileHandle(name, { create: true })).createWritable();
        await w.write(data);
        await w.close();
      };
      for (const f of outputs()) await write(f.path, f.name, f.data);
      let n = 0;
      for (const m of merged) {
        const when = new Map(m.sessions.map((s) => [s.id, day(s.createdAt)]));
        for (const p of m.photos) {
          const name = `${when.get(p.sessionId) ?? 'unknown'}_${p.sessionId.slice(0, 8)}_${p.step}.jpg`;
          await write(['사진', m.code], name, new Blob([unb64(p.jpeg) as BlobPart], { type: 'image/jpeg' }));
          n++;
        }
      }
      setMsg({
        tone: 'good',
        text: `저장했습니다: 피험자 ${merged.length}명 파일, _sessions.csv, _collect_log.json${n ? `, 사진 ${n}장(사진 폴더)` : ''}. 분석: python tools/analysis/pilot.py <이 폴더>`,
      });
    } catch (e) {
      console.warn('collect save failed', e);
      setMsg({ tone: 'danger', text: '저장하지 못했습니다. 다른 폴더를 골라 다시 시도해 주세요.' });
    } finally {
      setBusy(null);
    }
  };

  return (
    <>
      <AppBar title="연구 자료 모으기" sub="연구 PC · 인터넷 없이 동작" />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              연구 기기에서 만든 꾸러미 파일(.fpcr.json)을 열어 봉인과 사진을 다시 확인하고, 연구 코드별로 합쳐 분석 도구용 파일로
              저장합니다. 열린 자료는 이 화면에만 있고 브라우저에 남지 않습니다(닫으면 사라짐). 저장할 때는 암호화 드라이브의 폴더를
              고르세요.
            </span>
          </Notice>
        </div>

        <div class="section-title">1. 꾸러미 파일</div>
        <div
          class="card"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            void addFiles(e.dataTransfer?.files ?? null);
          }}
        >
          <label class="btn block">
            <Icon name="upload" /> 파일 고르기 (여러 개 가능, 끌어다 놓아도 됨)
            <input
              type="file"
              multiple
              accept=".json,application/json"
              style={{ display: 'none' }}
              onChange={(e) => {
                const input = e.target as HTMLInputElement;
                void addFiles(input.files).then(() => (input.value = ''));
              }}
            />
          </label>
          {loaded.length > 0 && (
            <table class="data" style={{ marginTop: '8px' }}>
              <thead>
                <tr>
                  <th>코드</th>
                  <th>만든 날</th>
                  <th>내용</th>
                  <th>상태</th>
                </tr>
              </thead>
              <tbody>
                {loaded.map((f) => {
                  const h = f.file?.header;
                  const o = openedBy.get(f.name);
                  return (
                    <tr>
                      <td>{h?.subjectCode ?? '–'}</td>
                      <td class="xsmall">{h ? fmtDate(h.exportedAt) : '–'}</td>
                      <td class="xsmall">
                        {h
                          ? `평가 ${h.counts.sessions} · 의료진 ${h.counts.ratings} · 사진 ${h.counts.photos}${h.consent.items.photos ? '' : ' (사진 동의 없음)'}`
                          : f.name}
                      </td>
                      <td class="xsmall">
                        {f.error
                          ? f.error === 'UNREADABLE'
                            ? '읽을 수 없음'
                            : '꾸러미 아님'
                          : !o
                            ? '열기 전'
                            : o.error
                              ? '열지 못함'
                              : `열림 · 봉인 ${o.seals.ok}/${o.seals.total} · 사진 ${o.photos.ok}/${o.photos.total}`}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        <div class="section-title">2. 연구 비밀번호로 열기</div>
        <div class="card">
          <input
            type="password"
            autoComplete="off"
            value={pw}
            aria-label="연구 비밀번호"
            placeholder="연구 비밀번호"
            style={{ width: '100%' }}
            onInput={(e) => setPw((e.target as HTMLInputElement).value)}
          />
          <button
            class="btn primary block"
            style={{ marginTop: '8px' }}
            disabled={!!busy || !loaded.some((f) => f.file) || !pw}
            onClick={openAll}
          >
            모두 열기
          </button>
        </div>

        {busy && <p class="small center ink2">{busy}</p>}
        {msg && (
          <div class="card tight">
            <Notice tone={msg.tone}>
              <span class="small">{msg.text}</span>
            </Notice>
          </div>
        )}

        {merged.length > 0 && (
          <>
            <div class="section-title">3. 피험자별로 합친 결과</div>
            <div class="card tight">
              <table class="data">
                <thead>
                  <tr>
                    <th>코드</th>
                    <th>평가</th>
                    <th>봉인</th>
                    <th>의료진</th>
                    <th>사진</th>
                    <th>동의(최근)</th>
                  </tr>
                </thead>
                <tbody>
                  {merged.map((m) => (
                    <tr>
                      <td>
                        {m.code}
                        <div class="xsmall muted">파일 {m.files.length}</div>
                      </td>
                      <td class="xsmall">
                        {m.sessions.length}
                        {m.sessions.length > 0 && ` (${day(m.sessions[0]!.createdAt)}~${day(m.sessions.at(-1)!.createdAt)})`}
                      </td>
                      <td class="xsmall">
                        {m.sessions.filter((s) => s.integrityVerified).length}/{m.sessions.length}
                      </td>
                      <td class="xsmall">{m.clinicianRatings.length}</td>
                      <td class="xsmall">{m.photos.length}</td>
                      <td class="xsmall">
                        사진 {m.latest.consent.items.photos ? 'O' : 'X'} · 2차 {m.latest.consent.items.secondaryUse ? 'O' : 'X'} · 인허가{' '}
                        {m.latest.consent.items.regulatory ? 'O' : 'X'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {merged
                .filter((m) => m.notes.length)
                .map((m) => (
                  <Notice tone="warn">
                    <span class="xsmall">
                      <b>{m.code}</b>: {m.notes.join(' · ')}
                    </span>
                  </Notice>
                ))}
            </div>

            <div class="section-title">4. 일치도 (전체, 앱 추정 vs 의료진)</div>
            <div class="card">
              <div class="tiles">
                <div class="tile">
                  <span class="label">Sunnybrook ICC(2,1) · n={ag.nComposite}</span>
                  <span class="value tabular">{f2(ag.iccComposite)}</span>
                </div>
                <div class="tile">
                  <span class="label">HB 가중 κ · n={ag.nHb}</span>
                  <span class="value tabular">{f2(ag.kappaHb)}</span>
                </div>
                <div class="tile">
                  <span class="label">Bland–Altman 편향 (95% LoA)</span>
                  <span class="value tabular" style={{ fontSize: '18px' }}>
                    {ag.ba ? `${ag.ba.bias.toFixed(1)} (${ag.ba.lower.toFixed(1)}~${ag.ba.upper.toFixed(1)})` : '–'}
                  </span>
                </div>
              </div>
              <p class="xsmall muted">
                평가마다 가장 최근 의료진 평가 하나와 비교한 간단 확인입니다. 계획서의 분석(두 평가자 평균, 방문별, 재측정)은 저장한 폴더로
                tools/analysis/pilot.py를 돌리세요.
              </p>
            </div>

            <div class="section-title">5. 저장</div>
            <div class="card">
              <button class="btn primary block" disabled={!!busy} onClick={save}>
                <Icon name="download" /> {pickDir ? '폴더에 저장 (분석 도구용)' : '파일로 내려받기'}
              </button>
              <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
                피험자마다 측정값 파일(이름 없음), 전체 평가 CSV, 작업 기록(_collect_log.json)을 저장하고, 동의가 있는 사진은 ‘사진’ 폴더에
                따로 둡니다(폴더 저장: ‘사진’ 폴더, 내려받기: _photos_코드.json). 통계 담당에게는 사진 없이 넘기세요.
              </p>
              <button
                class="btn ghost block"
                onClick={() => {
                  setLoaded([]);
                  setOpened([]);
                  setPw('');
                  setMsg(null);
                }}
              >
                화면에서 모두 지우기
              </button>
            </div>
          </>
        )}
      </main>
    </>
  );
}
